using System;using System.IO;using System.Net;using System.Diagnostics;using System.Threading;using System.Collections.Generic;using System.Security.Cryptography;using System.Text;using System.Web.Script.Serialization;
static class UpdateAgent {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=16000000};static readonly object Gate=new object();static string Root,Token;static bool VerifyMode,Checking;static Timer Clock;static Dictionary<string,object> Manifest,StagedManifest;static string Error="",CheckedAt="",Archive;static HashSet<string> Backups=new HashSet<string>();
 static Dictionary<string,object> Config(){return Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(Root,"updates.json")));}
 static string Value(Dictionary<string,object> d,string key){return d!=null&&d.ContainsKey(key)?Convert.ToString(d[key]):"";}
 static string Current(){return Value(Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(Root,"version.json"))),"version");}
 static bool Newer(string version){Version target,current;return Version.TryParse(version,out target)&&Version.TryParse(Current(),out current)&&target>current;}
 public static void Start(string root,bool verify){Root=root;VerifyMode=verify;ServicePointManager.SecurityProtocol=(SecurityProtocolType)3072;try{var config=Config();if(config.ContainsKey("enabled")&&Convert.ToBoolean(config["enabled"]))Clock=new Timer(_=>Check(),null,0,3600000);}catch{} }
 class Client:WebClient{protected override WebRequest GetWebRequest(Uri uri){var request=base.GetWebRequest(uri);request.Timeout=30000;return request;}}
 static Client Web(){var client=new Client();client.Headers["User-Agent"]="StarForge/"+Current();client.Headers["Cache-Control"]="no-cache";return client;}
 static Dictionary<string,object> Decode(string text,Dictionary<string,object> config){var signed=Json.Deserialize<Dictionary<string,object>>(text);string payload=Value(signed,"payload");byte[] signature=Convert.FromBase64String(Value(signed,"signature"));using(var rsa=new RSACryptoServiceProvider()){rsa.PersistKeyInCsp=false;rsa.FromXmlString(Value(config,"publicKey"));if(!rsa.VerifyData(Encoding.UTF8.GetBytes(payload),CryptoConfig.MapNameToOID("SHA256"),signature))throw new Exception("The update signature could not be verified.");}var manifest=Json.Deserialize<Dictionary<string,object>>(payload);Uri url;if(!Uri.TryCreate(Value(manifest,"url"),UriKind.Absolute,out url)||(url.Scheme!="https"&&!(VerifyMode&&url.IsLoopback))||!Value(manifest,"url").StartsWith(Value(config,"downloadPrefix"),StringComparison.Ordinal))throw new Exception("The update download location is not trusted.");Version version;if(!Version.TryParse(Value(manifest,"version"),out version))throw new Exception("Invalid update version.");if(!System.Text.RegularExpressions.Regex.IsMatch(Value(manifest,"sha256"),"^[a-fA-F0-9]{64}$"))throw new Exception("Invalid update checksum.");return manifest;}
 public static void Check(){lock(Gate){if(Checking)return;Checking=true;}try{var config=Config();if(!config.ContainsKey("enabled")||!Convert.ToBoolean(config["enabled"]))return;Uri feed=new Uri(Value(config,"feed"));if(feed.Scheme!="https"&&!(VerifyMode&&feed.IsLoopback))throw new Exception("Updates require a secure connection.");string text;using(var client=Web())text=client.DownloadString(feed);if(text.Length>64000)throw new Exception("The update feed is too large.");var manifest=Decode(text,config);lock(Gate){Manifest=manifest;Error="";CheckedAt=DateTime.UtcNow.ToString("o");}}
 catch(WebException error){lock(Gate){var response=error.Response as HttpWebResponse;Error=response!=null&&response.StatusCode==HttpStatusCode.NotFound?"No update has been published yet.":"Could not check for updates. Try again when connected to the internet.";CheckedAt=DateTime.UtcNow.ToString("o");}}
 catch(Exception error){lock(Gate){Manifest=null;Error=error.Message;CheckedAt=DateTime.UtcNow.ToString("o");}}
 finally{lock(Gate)Checking=false;} }
 public static string Status(){lock(Gate){return Json.Serialize(new{current=Current(),available=Manifest!=null&&Newer(Value(Manifest,"version")),version=Value(Manifest,"version"),notes=Value(Manifest,"notesUrl"),lastChecked=CheckedAt,error=Error,checking=Checking});}}
 static string Hash(string path){using(var sha=SHA256.Create())using(var stream=File.OpenRead(path))return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
 public static string Stage(){Dictionary<string,object> manifest;lock(Gate){if(Manifest==null||!Newer(Value(Manifest,"version")))throw new Exception("There is no newer update to install.");manifest=new Dictionary<string,object>(Manifest);}string folder=Path.Combine(Root,"Updates");Directory.CreateDirectory(folder);string archive=Path.Combine(folder,"download-"+Value(manifest,"version")+".zip"),temp=archive+".tmp";using(var client=Web())client.DownloadFile(Value(manifest,"url"),temp);long size=Convert.ToInt64(manifest["size"]);if(size<1||size>400000000||new FileInfo(temp).Length!=size||Hash(temp)!=Value(manifest,"sha256").ToLowerInvariant()){File.Delete(temp);throw new Exception("The update download did not pass its integrity check. Please try again.");}if(File.Exists(archive))File.Delete(archive);File.Move(temp,archive);lock(Gate){Archive=archive;StagedManifest=manifest;Token=Guid.NewGuid().ToString("N");}return Json.Serialize(new{token=Token,version=Value(manifest,"version")});}
 public static string Backup(string text){var project=Json.Deserialize<Dictionary<string,object>>(text);string schema=Value(project,"schema");if(schema!="starforge.level.v1"&&schema!="starforge.native.v1")throw new Exception("Unsupported project backup.");string folder=Path.Combine(Root,"Recovery");Directory.CreateDirectory(folder);string id=Guid.NewGuid().ToString("N"),path=Path.Combine(folder,"Before-update-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+id.Substring(0,6)+(schema=="starforge.native.v1"?".starstage.json":".starlevel"));File.WriteAllText(path,text,new UTF8Encoding(false));lock(Gate)Backups.Add(id);return Json.Serialize(new{backup=id});}
 public static string Install(string text,Action closeEditor){var request=Json.Deserialize<Dictionary<string,object>>(text);string token=Value(request,"token"),backup=Value(request,"backup"),archive;lock(Gate){if(token!=Token||!Backups.Contains(backup)||!File.Exists(Archive))throw new Exception("Download and save the project backup before installing.");archive=Archive;}
 foreach(var process in Process.GetProcessesByName("Starship")){try{if(String.Equals(process.MainModule.FileName,Path.Combine(Root,"NativeGame","Starship.exe"),StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Close the Starship playtest before updating. Your project is still open.");}catch(InvalidOperationException){throw;}catch{} }
 string folder=Path.Combine(Root,"Updates"),runner=Path.Combine(folder,"update-runner-"+Guid.NewGuid().ToString("N")+".exe"),job=Path.Combine(folder,"pending-update.json");File.Copy(Path.Combine(Root,"StarForgeUpdater.exe"),runner);File.WriteAllText(job,Json.Serialize(new{root=Root,archive=archive,sha256=Value(StagedManifest,"sha256").ToLowerInvariant(),version=Value(StagedManifest,"version"),hostPid=Process.GetCurrentProcess().Id}),new UTF8Encoding(false));Process.Start(new ProcessStartInfo(runner,"\""+job+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,WorkingDirectory=Root});ThreadPool.QueueUserWorkItem(_=>{Thread.Sleep(900);closeEditor();});return "{\"installing\":true}";
 }
}

